"""Migration of the Meridian CRM 4.2 credit-hold nightly sweep."""

from decimal import Decimal
from fractions import Fraction


def _numeric(value: object) -> Fraction:
    """Apply legacy NVL-style numeric coercion: missing or empty is zero."""
    if value is None:
        return Fraction(0)
    if isinstance(value, str):
        value = value.strip()
        if value == "":
            return Fraction(0)
    return Fraction(Decimal(str(value)))


def sweep(accounts: list[dict], orders: list[dict]) -> tuple[list[dict], list]:
    """Run the credit-hold sweep without mutating the supplied rows."""
    new_accounts = [account.copy() for account in accounts]
    audits: list[tuple[str, object]] = []

    live_invoiced_orders: dict[object, list[dict]] = {}
    for order in orders:
        if order.get("DEL_FLG") != "Y" and order.get("STAT_CD") == "I":
            live_invoiced_orders.setdefault(order.get("ACCT_ID"), []).append(order)

    account_indexes = sorted(
        range(len(new_accounts)),
        key=lambda index: new_accounts[index].get("ACCT_ID"),
    )

    for index in account_indexes:
        account = new_accounts[index]

        if account.get("DEL_FLG") == "Y" or account.get("ACCT_TYP") != "C":
            continue

        acct_id = account.get("ACCT_ID")
        exposure = sum(
            (_numeric(order.get("TOT_AMT")) for order in live_invoiced_orders.get(acct_id, [])),
            Fraction(0),
        )
        credit_limit = _numeric(account.get("CRED_LIMIT"))

        if exposure > credit_limit and account.get("CRED_HOLD") != "Y":
            account["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", acct_id))

        if exposure <= credit_limit * 8 / 10 and account.get("CRED_HOLD") == "Y":
            account["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", acct_id))

    return new_accounts, audits
